using Tempo.Blazor.Configuration;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

// Required: register core Tempo.Blazor services (ITmLocalizer, ThemeService, ToastService)
builder.Services.AddTempoBlazor();

// Compatibility option when using Tempo.Blazor.All instead of explicit feature registration
// builder.Services.AddTempoBlazorAll();

// Optional feature packages
builder.Services.AddTempoBlazorPdfViewer();
builder.Services.AddTempoBlazorCodes();
builder.Services.AddTempoBlazorDiagramEditor();
builder.Services.AddTempoBlazorDocumentEditor();
builder.Services.AddTempoBlazorNotionEditor();
builder.Services.AddTempoBlazorSigning();
builder.Services.AddTempoBlazorWireframe();
builder.Services.AddTempoBlazorModeling();
builder.Services.AddTempoBlazorSpreadsheet();
builder.Services.AddTempoBlazorGanttXlsx();

// Optional: register FluentValidation validators from your assemblies
builder.Services.AddTempoFluentValidation(typeof(MyValidator).Assembly);

// Optional: set culture for localization (supports 'en' and 'cs')
var culture = new System.Globalization.CultureInfo("cs");
System.Globalization.CultureInfo.DefaultThreadCurrentCulture = culture;
System.Globalization.CultureInfo.DefaultThreadCurrentUICulture = culture;

await builder.Build().RunAsync();

