customLocalizer.implementationExample:
using Tempo.Blazor.Localization;

public class MyCustomTmLocalizer : ITmLocalizer
{
    private readonly Dictionary<string, string> _strings = new()
    {
        ["Tm_Save"] = "Speichern",
        ["Tm_Cancel"] = "Abbrechen",
        ["Tm_Delete"] = "Löschen",
        ["Tm_Loading"] = "Wird geladen...",
        ["TmDataTable_NoResults"] = "Keine Ergebnisse gefunden",
        ["TmDataTable_SearchPlaceholder"] = "Suchen...",
        // ... add all 500+ keys for full coverage
    };

    public string this[string key] =>
        _strings.TryGetValue(key, out var value) ? value : key;

    public string this[string key, params object[] arguments] =>
        _strings.TryGetValue(key, out var value)
            ? string.Format(value, arguments)
            : string.Format(key, arguments);
}

partialOverride.code:
public class MyPartialLocalizer : ITmLocalizer
{
    private readonly ITmLocalizer _inner;
    private readonly Dictionary<string, string> _overrides = new()
    {
        ["Tm_Save"] = "Uložit a zavřít",
        ["TmDataTable_NoResults"] = "Žádné záznamy"
    };

    public MyPartialLocalizer(IStringLocalizer<TmResources> localizer)
    {
        _inner = new DefaultTmLocalizerWrapper(localizer);
    }

    public string this[string key] =>
        _overrides.TryGetValue(key, out var v) ? v : _inner[key];

    public string this[string key, params object[] arguments] =>
        _overrides.TryGetValue(key, out var v)
            ? string.Format(v, arguments) : _inner[key, arguments];
}
